<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Core\TenantFeatures;
use EventMenu\Services\TicketService;

$pdo=Database::connection();$slug=trim((string)($_GET['evento']??''));$error=null;$s=$pdo->prepare('SELECT e.*,t.name tenant_name FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$slug]);$event=$s->fetch();if(!$event||!TenantFeatures::events((int)($event['tenant_id']??0))){http_response_code(404);exit('Evento não encontrado.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada. Atualize a página.';else{try{$reservation=(new TicketService())->reservePublic((int)$event['id'],(int)($_POST['batch_id']??0),(int)($_POST['quantity']??1),['name'=>(string)($_POST['name']??''),'email'=>(string)($_POST['email']??''),'phone'=>(string)($_POST['phone']??'')],trim((string)($_POST['coupon']??''))?:null,trim((string)($_POST['promoter']??''))?:null);header('Location: '.app_url('pedido.php?t='.rawurlencode($reservation['public_token'])),true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
}
$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? AND active=1 ORDER BY id');$b->execute([$event['id']]);$batches=$b->fetchAll();function ev_money(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0f14"><title><?= Security::e($event['name']) ?> — EventMenu</title><link rel="stylesheet" href="<?= Security::e(app_url('assets/app.css')) ?>"><style>.event-shell{max-width:1080px;margin:auto;padding:32px 18px}.event-hero{padding:38px;border-radius:28px;background:linear-gradient(135deg,#181e2b,#11151c);border:1px solid var(--line);background-size:cover;background-position:center}.event-hero h1{font-size:clamp(34px,7vw,72px);line-height:.95;margin:20px 0}.ticket-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin-top:20px}.buy-form{display:grid;gap:9px;margin-top:14px}</style></head><body><main class="event-shell"><section class="event-hero"<?php if($event['banner_url']):?> style="background-image:linear-gradient(135deg,rgba(12,15,20,.88),rgba(12,15,20,.68)),url('<?= Security::e($event['banner_url']) ?>')"<?php endif;?>><div class="brand">EventMenu <span>Premium</span></div><p class="muted"><?= Security::e($event['tenant_name']) ?></p><h1><?= Security::e($event['name']) ?></h1><p><?= nl2br(Security::e($event['description'])) ?></p><p><strong><?= Security::e(date('d/m/Y H:i',strtotime($event['starts_at']))) ?></strong><br><?= Security::e($event['venue']) ?><br><span class="muted"><?= Security::e($event['address']) ?></span></p></section><?php if($error):?><div class="alert error" style="margin-top:18px"><?= Security::e($error) ?></div><?php endif;?><section style="margin-top:24px"><div class="section-head"><h2>Ingressos</h2><span class="muted">Pagos ficam reservados por 15 minutos até confirmação · gratuitos são emitidos na hora</span></div><div class="ticket-grid"><?php foreach($batches as $batch):$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved']);$now=time();$open=(!$batch['sales_start']||strtotime($batch['sales_start'])<=$now)&&(!$batch['sales_end']||strtotime($batch['sales_end'])>=$now);$free=(int)$batch['price_cents']===0;?><article class="card"><span class="badge"><?= Security::e($batch['name']) ?></span><h2><?= $free?'Grátis':ev_money((int)$batch['price_cents']) ?></h2><p class="muted"><?= $available ?> disponíveis</p><?php if($available>0&&$open):?><form method="post" class="buy-form"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label>Quantidade<select name="quantity"><?php for($i=1;$i<=min(10,$available);$i++):?><option value="<?= $i ?>"><?= $i ?></option><?php endfor;?></select></label><label>Nome<input name="name" required autocomplete="name"></label><label>E-mail<input type="email" name="email" autocomplete="email"></label><label>Telefone<input name="phone" autocomplete="tel"></label><label>Cupom <span class="muted">(opcional)</span><input name="coupon"></label><label>Código do promotor <span class="muted">(opcional)</span><input name="promoter"></label><button class="primary"><?= $free?'Emitir ingresso':'Reservar e pagar' ?></button></form><?php elseif(!$open):?><span class="badge">Fora do período de venda</span><?php else:?><span class="badge">Esgotado</span><?php endif;?></article><?php endforeach;?></div></section></main></body></html>
